def value_kind(value):
    """Classify one non-null value, using the most specific valid type."""
    for typ in ("timestamp", "date", "bool", "int", "float"):
        try:
            parse_as(value, typ)
            return typ
        except (ValueError, OverflowError):
            pass
    return "string"


def kind_for_values(values):
    for typ in sorted(TYPES[1:], key=lambda x: TYPE_PRIORITY[x], reverse=True):
        try:
            for value in values:
                parse_as(value, typ)
            return typ
        except (ValueError, OverflowError):
            continue
    return "string"


def infer_schema(paths, infer_mode, quotechar, escapechar):
    names = set()
    per_file = {}
    for path in paths:
        with open(path, "r", encoding="utf-8", newline="") as f:
            reader = csv.reader(f, delimiter=",", quotechar=quotechar,
                                escapechar=escapechar, doublequote=escapechar is None)
            try:
                header = next(reader)
            except StopIteration:
                raise ValueError(f"input is missing a header: {path}")
            if len(set(header)) != len(header):
                raise ValueError(f"duplicate column in header: {path}")
            names.update(header)
            observed = {name: [] for name in header}
            for row in reader:
                for i, name in enumerate(header):
                    if i < len(row) and row[i] != "":
                        observed[name].append(row[i])
            per_file[path] = observed

    result = []
    for name in sorted(names):
        files_seen = []
        all_values = []
        for observed in per_file.values():
            vals = observed.get(name, [])
            if vals:
                all_values.extend(vals)
                files_seen.append(kind_for_values(vals))
        if not all_values:
            typ = "string"
        elif infer_mode == "strict":
            typ = files_seen[0] if files_seen and len(set(files_seen)) == 1 else "string"
        else:
            typ = "string"
            # The priority order makes the choice deterministic when multiple
            # interpretations are possible (for example, "1" is also numeric).
            typ = kind_for_values(all_values)
        result.append((name, typ))
    return result


